export function formatCoverageReport(report: CoverageReport): string {
  const lines = [
    `# i18n coverage (${report.filters.policy}${report.filters.space ? `, ${report.filters.space}` : ""})`,
    "",
    "| Space | Locale | Tier | Policy | Coverage | Translated | Untranslated |",
    "| --- | --- | --- | --- | ---: | ---: | ---: |",
  ];
  for (const row of report.rows) {
    lines.push(
      `| ${row.space} | ${row.locale} | ${row.tier ?? "unmatched"} | ${row.policy} | ${row.percent}% | ${row.translated}/${row.total} | ${row.untranslated} |`,
    );
  }
  return `${lines.join("\n")}\n`;
}

/** Escape text for safe interpolation into HTML markup or a `data-*` attribute value. */
function escapeHtml(value: string): string {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");
}

function distinctSorted(values: readonly string[]): string[] {
  return [...new Set(values)].sort((a, b) => a.localeCompare(b));
}

function optionsHtml(values: readonly string[]): string {
  return values.map((value) => `<option value="${escapeHtml(value)}">${escapeHtml(value)}</option>`).join("");
}

/** Render a self-contained, sortable/filterable HTML coverage report — a pantoken-styled table
 *  that runs entirely client-side (no build step or external assets) over the same rows
 *  `writeCoverageReport` persisted as JSON. */
export function formatCoverageReportHtml(report: CoverageReport): string {
  const rowsHtml = report.rows
    .map((row) => {
      const tier = row.tier ?? "unmatched";
      return `<tr data-space="${escapeHtml(row.space)}" data-locale="${escapeHtml(row.locale)}" data-tier="${escapeHtml(tier)}" data-policy="${escapeHtml(row.policy)}" data-percent="${String(row.percent)}" data-translated="${String(row.translated)}" data-untranslated="${String(row.untranslated)}" data-total="${String(row.total)}">
        <td>${escapeHtml(row.space)}</td>
        <td>${escapeHtml(row.locale)}</td>
        <td>${escapeHtml(tier)}</td>
        <td><span class="policy policy-${escapeHtml(row.policy)}">${escapeHtml(row.policy)}</span></td>
        <td class="num"><div class="bar"><div class="bar-fill" style="width:${String(row.percent)}%"></div><span>${String(row.percent)}%</span></div></td>
        <td class="num">${String(row.translated)}</td>
        <td class="num">${String(row.untranslated)}</td>
        <td class="num">${String(row.total)}</td>
      </tr>`;
    })
    .join("\n");
  const spaceOptions = optionsHtml(distinctSorted(report.rows.map((row) => row.space)));
  const tierOptions = optionsHtml(distinctSorted(report.rows.map((row) => row.tier ?? "unmatched")));
  const policyOptions = optionsHtml(distinctSorted(report.rows.map((row) => row.policy)));
  const title = `i18n coverage (${report.filters.policy}${report.filters.space ? `, ${escapeHtml(report.filters.space)}` : ""})`;
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${title}</title>
<style>
  :root {
    color-scheme: light dark;
    --i18n-accent: #0374b5;
    --i18n-border: #d5dae1;
    --i18n-background: #f5f7fa;
    --i18n-surface: #ffffff;
    --i18n-text: #1a2733;
    --i18n-muted: #5c6b79;
  }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    padding: 2rem;
    background: var(--i18n-background);
    color: var(--i18n-text);
    font-family: -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    font-size: 0.9375rem;
  }
  h1 { margin: 0 0 0.25rem; font-size: 1.375rem; }
  .meta { margin: 0 0 1.5rem; color: var(--i18n-muted); }
  .toolbar {
    display: flex;
    flex-wrap: wrap;
    gap: 0.75rem;
    margin-bottom: 1rem;
  }
  .toolbar input, .toolbar select {
    padding: 0.4rem 0.6rem;
    border: 1px solid var(--i18n-border);
    border-radius: 0.375rem;
    background: var(--i18n-surface);
    color: inherit;
    font-size: 0.875rem;
  }
  .toolbar input { flex: 1 1 16rem; }
  table {
    width: 100%;
    border-collapse: collapse;
    background: var(--i18n-surface);
    border: 1px solid var(--i18n-border);
    border-radius: 0.5rem;
    overflow: hidden;
  }
  caption { text-align: start; padding: 0.5rem 0.75rem; color: var(--i18n-muted); }
  th, td {
    padding: 0.5rem 0.75rem;
    border-bottom: 1px solid var(--i18n-border);
    text-align: start;
  }
  td.num, th.num { text-align: end; }
  thead th {
    background: var(--i18n-background);
    font-weight: 600;
    cursor: pointer;
    user-select: none;
    white-space: nowrap;
  }
  thead th[data-sort="asc"]::after { content: " \\25B2"; }
  thead th[data-sort="desc"]::after { content: " \\25BC"; }
  tbody tr:hover { background: color-mix(in srgb, var(--i18n-accent) 6%, transparent); }
  tbody tr[hidden] { display: none; }
  .policy { padding: 0.1rem 0.5rem; border-radius: 1rem; font-size: 0.8125rem; font-weight: 600; }
  .policy-block { background: #fbe4e4; color: #9b1c1c; }
  .policy-warn { background: #fdf1d0; color: #8a5d00; }
  .policy-off { background: #e4e9ee; color: var(--i18n-muted); }
  .bar { display: flex; align-items: center; gap: 0.5rem; justify-content: flex-end; }
  .bar-fill {
    height: 0.5rem;
    width: 4rem;
    max-width: 4rem;
    border-radius: 0.25rem;
    background: color-mix(in srgb, var(--i18n-accent) 100%, transparent);
    flex: 0 0 auto;
  }
  .bar > .bar-fill { flex-basis: 4rem; }
  .bar-track { position: relative; }
  #visible-count { font-weight: 600; }
</style>
</head>
<body>
  <h1>i18n coverage</h1>
  <p class="meta">Generated ${escapeHtml(report.generatedAt)} from source locale <strong>${escapeHtml(report.source)}</strong> &mdash; policy filter: ${escapeHtml(report.filters.policy)}${report.filters.space ? `, space: ${escapeHtml(report.filters.space)}` : ""}. Showing <span id="visible-count"></span> of ${String(report.rows.length)} rows.</p>
  <div class="toolbar">
    <input id="search" type="search" placeholder="Filter by space or locale&hellip;" aria-label="Filter rows">
    <select id="filter-space" aria-label="Filter by space"><option value="">All spaces</option>${spaceOptions}</select>
    <select id="filter-tier" aria-label="Filter by tier"><option value="">All tiers</option>${tierOptions}</select>
    <select id="filter-policy" aria-label="Filter by policy"><option value="">All policies</option>${policyOptions}</select>
  </div>
  <table>
    <caption>${title}</caption>
    <thead>
      <tr>
        <th data-key="space" data-type="string">Space</th>
        <th data-key="locale" data-type="string">Locale</th>
        <th data-key="tier" data-type="string">Tier</th>
        <th data-key="policy" data-type="string">Policy</th>
        <th data-key="percent" data-type="number" class="num">Coverage</th>
        <th data-key="translated" data-type="number" class="num">Translated</th>
        <th data-key="untranslated" data-type="number" class="num">Untranslated</th>
        <th data-key="total" data-type="number" class="num">Total</th>
      </tr>
    </thead>
    <tbody>
${rowsHtml}
    </tbody>
  </table>
<script>
(function () {
  var table = document.querySelector("table");
  var tbody = table.tBodies[0];
  var rows = Array.prototype.slice.call(tbody.rows);
  var state = { key: null, dir: 1 };

  function compare(a, b, key, type) {
    var av = type === "number" ? Number(a.dataset[key]) : a.dataset[key].toLowerCase();
    var bv = type === "number" ? Number(b.dataset[key]) : b.dataset[key].toLowerCase();
    if (av < bv) return -1;
    if (av > bv) return 1;
    return 0;
  }

  Array.prototype.forEach.call(table.tHead.querySelectorAll("th[data-key]"), function (th) {
    th.addEventListener("click", function () {
      var key = th.dataset.key;
      var type = th.dataset.type;
      state.dir = state.key === key ? -state.dir : 1;
      state.key = key;
      Array.prototype.forEach.call(table.tHead.querySelectorAll("th"), function (h) {
        h.removeAttribute("data-sort");
      });
      th.setAttribute("data-sort", state.dir === 1 ? "asc" : "desc");
      rows.sort(function (a, b) { return state.dir * compare(a, b, key, type); });
      rows.forEach(function (row) { tbody.appendChild(row); });
    });
  });

  var search = document.getElementById("search");
  var spaceFilter = document.getElementById("filter-space");
  var tierFilter = document.getElementById("filter-tier");
  var policyFilter = document.getElementById("filter-policy");
  var visibleCount = document.getElementById("visible-count");

  function applyFilters() {
    var q = search.value.trim().toLowerCase();
    var space = spaceFilter.value;
    var tier = tierFilter.value;
    var policy = policyFilter.value;
    var visible = 0;
    rows.forEach(function (row) {
      var matchesQuery = !q || row.textContent.toLowerCase().indexOf(q) !== -1;
      var matchesSpace = !space || row.dataset.space === space;
      var matchesTier = !tier || row.dataset.tier === tier;
      var matchesPolicy = !policy || row.dataset.policy === policy;
      var show = matchesQuery && matchesSpace && matchesTier && matchesPolicy;
      row.hidden = !show;
      if (show) visible++;
    });
    visibleCount.textContent = String(visible);
  }

  search.addEventListener("input", applyFilters);
  spaceFilter.addEventListener("change", applyFilters);
  tierFilter.addEventListener("change", applyFilters);
  policyFilter.addEventListener("change", applyFilters);
  applyFilters();
})();
</script>
</body>
</html>
`;
}"}

